def gen_strings(n=2000, seed=42):
    rng = random.Random(seed)
    pools = [
        string.ascii_letters + string.digits + " \t\n%/_:?&=#-._~",
        "".join(chr(i) for i in range(0xA0, 0x100)),  # Latin-1 supplement
        "".join(chr(i) for i in range(0x1F300, 0x1F64F)),  # emoji
    ]
    for _ in range(n):
        pool = rng.choice(pools)
        length = rng.randint(0, 30)
        yield "".join(rng.choice(pool) for _ in range(length))


def test_differential():
    for s in gen_strings():
        for safe in SAFE_SETS:
            assert quote(s, safe) == ref_quote(s, safe), (s, safe)
            assert unquote(s) == ref_unquote(s), (s,)


def test_roundtrip():
    for s in gen_strings():
        assert unquote(quote(s)) == s


